            d = row['d']
        if 'r' in row:
            r = row['r']
        # At the sampled posedge clk:
        # sync_active_high_reset: r == 1 updates q to 0 regardless of d.
        # d_capture_when_not_reset: r == 0 updates q to sampled d.
        if r == 1:
            q = 0
        else:
            q = d
